// Every click, change and input on the page, handled by delegation from the document.
import {demo} from '../demo.js';
import {tradeCandidateIds} from '../engine.js';
import {compareTradeIdeas} from '../trades.js';
import {S} from './state.js';
import {$,failedHeadshots,isLeagueView,isTradeView,league,toast} from './core.js';
import {ensureTradeOutlook,seasonModel} from './outlook.js';
import {RADAR_COLORS} from './pages/charts.js';
import {currentLeagueOutlook,ensureLeagueSeason} from './pages/league-outlook.js';
import {ensureRecap,ensureSeasonPage} from './pages/season-review.js';
import {askFor,partnerName,suggestTrades,tradeEval,tradeInput} from './pages/trade-finder.js';
import {ensureWaiverOutlook,protectedPlayers,protectionKey} from './pages/waiver-wire.js';
import {observeScores,scheduleScoreCleanup,watchCards} from './pages/watchroom.js';
import {rememberPage,render} from './render.js';
import {connect,refresh,savePrefs} from './session.js';
import {selectTheme,themePicker} from './theme.js';

export function bindEvents(){
 document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&img.classList.contains('player-headshot')){failedHeadshots.add(img.dataset.photoId);img.hidden=true;img.parentElement.title='Photo unavailable';}},true);
 document.addEventListener('click',e=>{const t=e.target;if(t.closest('#shop-clear')){askFor('any','');return}if(t.closest('#open-theme')){themePicker();$('#theme-dialog').showModal();$('#theme-team').focus();return}if(t.closest('#close-theme')){$('#theme-dialog').close();$('#open-theme')?.focus();return}if(t.closest('#reset-theme')){selectTheme('default');return}if(t.closest('[data-shop]')){const id=t.closest('[data-shop]').dataset.shop;S.view='trades';rememberPage();render();window.scrollTo({top:0});ensureTradeOutlook().then(()=>askFor('shop',id));return}const n=t.closest('[data-nav]');if(n){if(n.dataset.nav==='notifications'){location.href='/integrations.html';return}S.view=n.dataset.nav;rememberPage();render();if(S.view==='season')ensureSeasonPage();if(isLeagueView())ensureLeagueSeason();if(isTradeView())ensureTradeOutlook();if(S.view==='waivers')ensureWaiverOutlook();window.scrollTo({top:0});return}if(t.closest('[data-connect]')){if(S.serviceMode){S.view='settings';rememberPage();render();window.scrollTo({top:0});return}$('#username').value=S.prefs.username||'';$('#connect-error').textContent='';$('#connect').showModal();$('#username').focus()}if(t.closest('#cancel-connect')){S.connectRun++;$('#connect').close()}if(t.closest('#score-effects')){S.prefs.scoreEffects=S.prefs.scoreEffects===false;savePrefs();render()}if(t.closest('#preview-score')){S.previewPlayer=$('#players .player-card')?.dataset.playerId||null;if(S.previewPlayer){S.prefs.scoreEffects=true;savePrefs();scheduleScoreCleanup();render();toast('Highlight preview only — player scores are unchanged.')}}if(t.closest('#focus')){S.focus=!S.focus;render()}const opens=t.closest('[data-open-game]');if(opens&&!t.closest('[data-nav]')){S.openGame=opens.dataset.openGame;render();window.scrollTo({top:0});return}if(t.closest('[data-close-game]')){S.openGame=null;render();return}const myGame=t.closest('[data-my-game]');if(myGame){const l=S.data.leagues.find(l=>l.league_id===myGame.dataset.myGame),m=l?.matchups.find(m=>m.roster_id===l.mine.roster_id),pair=m?.matchup_id==null?null:l.matchups.filter(x=>x.matchup_id===m.matchup_id).map(x=>x.roster_id);S.leagueId=l.league_id;S.view='scoreboard';S.openGame=null;savePrefs();rememberPage();render();window.scrollTo({top:0});ensureLeagueSeason().then(()=>{const o=currentLeagueOutlook(),g=pair&&o?.live.games.find(g=>pair.every(id=>g.teams.includes(id)));if(g&&S.view==='scoreboard'){S.openGame=g.teams.join(':');render()}});return}const depthTarget=t.closest('[data-depth-target]');if(depthTarget){const want=depthTarget.dataset.depthTarget;S.view='trades';rememberPage();window.scrollTo({top:0});ensureTradeOutlook().then(()=>askFor('position',want));askFor('position',want);return}if(t.closest('[data-depth-clear]')){askFor('any','');return}const radarTeam=t.closest('[data-radar-team]');if(radarTeam){const id=Number(radarTeam.dataset.radarTeam),mine=league()?.mine?.roster_id===id;if(S.radarPicks.has(id))S.radarPicks.delete(id);else if(mine)S.radarPicks.set(id,-1);else{const free=RADAR_COLORS.findIndex((_,i)=>![...S.radarPicks.values()].includes(i));if(free<0){toast('Four teams at a time. Take one off first.');return}S.radarPicks.set(id,free)}render();return}if(t.closest('[data-radar-all]')){S.radarAll=!S.radarAll;render();return}if(t.closest('[data-radar-reset]')){S.radarLeague=null;render();return}const basis=t.closest('[data-league-basis]');if(basis){S.leagueBasis=basis.dataset.leagueBasis;S.prefs.leagueBasis=S.leagueBasis;savePrefs();render();return}const f=t.closest('[data-filter]');if(f){S.filter=f.dataset.filter;savePrefs();render()}const p=t.closest('[data-pin]');if(p){S.pins.has(p.dataset.pin)?S.pins.delete(p.dataset.pin):S.pins.add(p.dataset.pin);savePrefs();render()}if(t.closest('#refresh')){refresh(true,true);if(isLeagueView())ensureLeagueSeason(true)}if(t.closest('#refresh-recap')){ensureRecap(true);return}if(t.closest('#refresh-waiver')){if(S.waiverHorizon==='current')refresh(true,true);else ensureWaiverOutlook(true)}if(t.closest('#disconnect')){if(S.serviceMode){location.href='/integrations.html';return}S.connectRun++;S.prefs.username=null;S.prefs.disabled=[];S.data=demo();S.leagueId=S.data.leagues[0].league_id;S.watchLeague='all';S.give=[];S.get=[];S.tradeManual=null;S.tradeSuggestions=null;savePrefs();observeScores();render();toast('Disconnected. Sample data is now displayed.')}if(t.closest('#load-trade-season'))ensureTradeOutlook(true);if(t.closest('#trade-fit-defaults')){S.tradeMinGain=0;S.tradeMaxGap=1;S.penalty=.15;S.tradeRun++;savePrefs();render();suggestTrades()}if(t.closest('#more-trades')){const next=S.tradeSuggestions?.length||0;S.tradeVisible+=5;render();const offer=document.querySelectorAll('.trade-offer')[next];offer?.focus({preventScroll:true});offer?.scrollIntoView({block:'start'});return}if(t.closest('#suggest-trades')){if(S.tradeAsk==='shop'||S.tradeAsk==='get'){if(S.shopId)askFor(S.tradeAsk,S.shopId)}else suggestTrades();return}if(t.closest('#analyze-trade')){const l=league(),p=tradeInput(l);try{const r=tradeEval(l,p,S.give,S.get);S.tradeManual={...r,model:seasonModel(l),give:[...S.give],get:[...S.get],partner:partnerName(l,p),partnerId:p.roster_id};render()}catch(e){toast(e.message)}}});
// League cards act as buttons, so they answer Enter and Space too.
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-my-game]')){e.preventDefault();e.target.click()}});
 document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){S.query=t.value;$('#players').innerHTML=watchCards()}if(t.id==='penalty'){S.penalty=Number(t.value)/100;$('#penalty-label').textContent=Math.round(S.penalty*100)+'%'}});
 document.addEventListener('change',async e=>{const t=e.target;if(t.id==='theme-team'){selectTheme(t.value);return}if(t.id==='trade-ask'){askFor(t.value,'');return}if(t.id==='trade-subject'){askFor(S.tradeAsk,t.value);return}if(t.id==='trade-sort'){S.tradeSort=t.value;S.prefs.tradeSort=S.tradeSort;S.tradeVisible=5;savePrefs();render();return}if(t.id==='recap-week'){S.recapWeek=Number(t.value);render();ensureRecap();return}if(t.id==='waiver-horizon'||t.id==='waiver-end-week'){if(t.id==='waiver-horizon')S.waiverHorizon=t.value;else S.waiverEndWeek=Number(t.value);savePrefs();render();ensureWaiverOutlook();return}if(['trade-min-gain','trade-max-gap','trade-end-week'].includes(t.id)){if(t.id==='trade-min-gain')S.tradeMinGain=Number(t.value);if(t.id==='trade-max-gap')S.tradeMaxGap=Number(t.value);if(t.id==='trade-end-week')S.tradeEndWeek=Number(t.value);S.tradeRun++;S.tradeSuggestions=null;S.tradeManual=null;savePrefs();render();if(t.id==='trade-end-week')ensureTradeOutlook();return}if(t.dataset.waiverPosition){const side=t.dataset.waiverPosition;S.waiverExcluded[side]=t.checked?S.waiverExcluded[side].filter(p=>p!==t.value):[...new Set([...S.waiverExcluded[side],t.value])];savePrefs();render();return}if(t.id==='waiver-upgrades-only'){S.waiverUpgradesOnly=t.checked;savePrefs();render();return}if(t.dataset.protectPlayer){const l=league(),key=protectionKey(l),ids=protectedPlayers(l);S.prefs.waiverProtected||={};S.prefs.waiverProtected[key]=t.checked?[...new Set([...ids,t.dataset.protectPlayer])]:ids.filter(id=>id!==t.dataset.protectPlayer);savePrefs();render();return}if(t.id==='protect-starters'||t.id==='same-position-drops'){if(t.id==='protect-starters')S.protectStarters=t.checked;else S.samePositionDrops=t.checked;savePrefs();render();return}if(t.dataset.tradePosition){const side=t.dataset.tradePosition;S.tradeExcluded[side]=t.checked?S.tradeExcluded[side].filter(p=>p!==t.value):[...new Set([...S.tradeExcluded[side],t.value])];S.prefs.tradeExcluded=S.tradeExcluded;savePrefs();S.give=tradeCandidateIds(S.give,S.data.players,S.tradeExcluded.give);S.get=tradeCandidateIds(S.get,S.data.players,S.tradeExcluded.get);S.tradeRun++;S.tradeSuggestions=null;S.tradeManual=null;render();return}if(t.id==='analysis-league'){S.leagueId=t.value;S.tradeAsk='any';S.tradeTarget=null;S.shopId='';S.shopResult=null;S.openGame=null;S.give=[];S.get=[];S.tradeSuggestions=null;S.tradeManual=null;S.tradeRun++;savePrefs();render();if(isTradeView())ensureTradeOutlook();if(isLeagueView())ensureLeagueSeason();if(S.view==='season')ensureRecap()}if(t.id==='watch-league'){S.watchLeague=t.value;savePrefs();render()}if(t.id==='watch-role'){S.watchRole=t.value;S.prefs.watchRole=S.watchRole;savePrefs();render()}if(t.id==='bench'){S.bench=t.checked;savePrefs();render()}if(t.id==='trade-partner'){S.partnerId=t.value;S.get=[];S.tradeManual=null;render()}if(t.id==='require-benefit'){S.requireBenefit=t.checked;S.tradeSuggestions=null;savePrefs();render()}if(t.id==='penalty'){savePrefs();if(S.tradeSuggestions)S.tradeSuggestions.sort((a,b)=>compareTradeIdeas(a,b,S.penalty));render()}if(t.dataset.trade){let list=t.dataset.trade==='give'?S.give:S.get;list=t.checked?[...list,t.value]:list.filter(id=>id!==t.value);if(t.dataset.trade==='give')S.give=list;else S.get=list;S.tradeManual=null}if(t.dataset.leagueToggle){const l=S.data.leagues.find(l=>l.league_id===t.dataset.leagueToggle);l.enabled=t.checked;S.watchLeague='all';S.tradeSuggestions=null;S.tradeManual=null;savePrefs();render()}if(t.id==='week'){if(S.serviceMode){toast('Background service follows the current NFL week.');render();return}const week=Number(t.value);if(S.data.demo){toast('The demo illustrates Week 2. Connect Sleeper to browse other weeks.');render();return}if(S.busy){toast('Wait for the current refresh to finish.');render();return}S.data.week=week;S.data.games={};S.data.leagues=S.data.leagues.map(l=>({...l,matchups:[]}));S.tradeSuggestions=null;S.tradeManual=null;await refresh(true)}});
 $('#connect-form').addEventListener('submit',e=>{e.preventDefault();const u=$('#username').value.trim();if(u)connect(u)});
 $('#connect').addEventListener('cancel',()=>S.connectRun++);
 setInterval(()=>{if(!document.hidden&&(!S.data.demo||S.serviceMode))refresh(true)},45000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&(!S.data.demo||S.serviceMode)&&Date.now()-S.data.updatedAt>45000)refresh(true)});
}
